def transform(grid):
    # A uniform non-background divider splits two equal-sized masks.
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        if row and len(set(row)) == 1 and row[0] != 0 and r == h - r - 1:
            top, bottom = grid[:r], grid[r + 1:]
            return [[2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
                    for ra, rb in zip(top, bottom)]
    for c in range(w):
        if (all(grid[r][c] == grid[0][c] != 0 for r in range(h))
                and c == w - c - 1):
            return [[2 if row[j] != 0 and row[c + 1 + j] != 0 else 0
                     for j in range(c)] for row in grid]
    raise ValueError('No centered uniform divider found')
